export type CreateMswHandlersResult = {
    all: (options?: {
        pick?: {
            [K in keyof MswHandlerFactories]?: Parameters<MswHandlerFactories[K]>[0] | Parameters<MswHandlerFactories[K]>;
        };
    }) => ReadonlyArray<HttpHandler>;
    pick: MswHandlerFactories;
};

export function createMswHandlers(config: RequestHandlerOptions = {}): CreateMswHandlersResult {
    type Handler<R> = (response?: R, options?: RequestHandlerOptions) => HttpHandler;
    function wrap<R>(handler: Handler<R>): Handler<R> {
        return (response, options) => handler(response, { ...config, ...options });
    }
    const pick: CreateMswHandlersResult['pick'] = {
        listWorlds: wrap(handleListWorlds),
        createWorld: wrap(handleCreateWorld),
        dropWorld: wrap(handleDropWorld),
        getAbilitiesBySkill: wrap(handleGetAbilitiesBySkill),
        getCreatureAbilities: wrap(handleGetCreatureAbilities),
        getCreatureInventory: wrap(handleGetCreatureInventory),
        getCreatureConsumables: wrap(handleGetCreatureConsumables),
        getCreatureAttributePoints: wrap(handleGetCreatureAttributePoints),
        allocateCreatureAttributePoints: wrap(handleAllocateCreatureAttributePoints),
        getCreatureBaseAttributes: wrap(handleGetCreatureBaseAttributes),
        getCreatureAttributes: wrap(handleGetCreatureAttributes),
        getCreatureBasicAttackDamage: wrap(handleGetCreatureBasicAttackDamage),
        getCreatureSkills: wrap(handleGetCreatureSkills),
        getCreatureLevel: wrap(handleGetCreatureLevel),
        equipCreatureItem: wrap(handleEquipCreatureItem),
        unequipCreatureItem: wrap(handleUnequipCreatureItem),
        previewCreatureEquipment: wrap(handlePreviewCreatureEquipment),
        previewCreatureBasicAttackDamage: wrap(handlePreviewCreatureBasicAttackDamage),
        getNearbyCorpses: wrap(handleGetNearbyCorpses),
        getPlayerFight: wrap(handleGetPlayerFight),
        getPlayerFightAbilities: wrap(handleGetPlayerFightAbilities),
        getCreatureGenerationOptions: wrap(handleGetCreatureGenerationOptions),
        createSession: wrap(handleCreateSession),
        getSessionScene: wrap(handleGetSessionScene),
        listSessionLoreAnchors: wrap(handleListSessionLoreAnchors),
        getSessionLoreAnchor: wrap(handleGetSessionLoreAnchor),
        getJob: wrap(handleGetJob),
        transferInventory: wrap(handleTransferInventory),
        getTrade: wrap(handleGetTrade),
        proposeTrade: wrap(handleProposeTrade),
        completeTrade: wrap(handleCompleteTrade),
        getSessionItem: wrap(handleGetSessionItem),
        getQuestJournal: wrap(handleGetQuestJournal),
        acceptQuest: wrap(handleAcceptQuest),
        completeQuest: wrap(handleCompleteQuest),
        setQuestTracking: wrap(handleSetQuestTracking)
    };
    const all: CreateMswHandlersResult['all'] = (options = {}) => {
        type OverrideValue<R> = R | [
            response?: R,
            options?: RequestHandlerOptions
        ];
        function invoke<R>(fn: Handler<R>, override?: OverrideValue<R>): HttpHandler {
            return Array.isArray(override) ? fn(...override) : fn(override);
        }
        const overrides = options.pick ?? {};
        return [
            invoke(pick.previewCreatureBasicAttackDamage, overrides.previewCreatureBasicAttackDamage),
            invoke(pick.proposeTrade, overrides.proposeTrade),
            invoke(pick.completeTrade, overrides.completeTrade),
            invoke(pick.acceptQuest, overrides.acceptQuest),
            invoke(pick.completeQuest, overrides.completeQuest),
            invoke(pick.setQuestTracking, overrides.setQuestTracking),
            invoke(pick.previewCreatureEquipment, overrides.previewCreatureEquipment),
            invoke(pick.getPlayerFightAbilities, overrides.getPlayerFightAbilities),
            invoke(pick.unequipCreatureItem, overrides.unequipCreatureItem),
            invoke(pick.getSessionLoreAnchor, overrides.getSessionLoreAnchor),
            invoke(pick.getTrade, overrides.getTrade),
            invoke(pick.getSessionItem, overrides.getSessionItem),
            invoke(pick.getCreatureAbilities, overrides.getCreatureAbilities),
            invoke(pick.getCreatureInventory, overrides.getCreatureInventory),
            invoke(pick.getCreatureConsumables, overrides.getCreatureConsumables),
            invoke(pick.getCreatureAttributePoints, overrides.getCreatureAttributePoints),
            invoke(pick.allocateCreatureAttributePoints, overrides.allocateCreatureAttributePoints),
            invoke(pick.getCreatureBaseAttributes, overrides.getCreatureBaseAttributes),
            invoke(pick.getCreatureAttributes, overrides.getCreatureAttributes),
            invoke(pick.getCreatureBasicAttackDamage, overrides.getCreatureBasicAttackDamage),
            invoke(pick.getCreatureSkills, overrides.getCreatureSkills),
            invoke(pick.getCreatureLevel, overrides.getCreatureLevel),
            invoke(pick.equipCreatureItem, overrides.equipCreatureItem),
            invoke(pick.getNearbyCorpses, overrides.getNearbyCorpses),
            invoke(pick.getPlayerFight, overrides.getPlayerFight),
            invoke(pick.getSessionScene, overrides.getSessionScene),
            invoke(pick.listSessionLoreAnchors, overrides.listSessionLoreAnchors),
            invoke(pick.transferInventory, overrides.transferInventory),
            invoke(pick.getQuestJournal, overrides.getQuestJournal),
            invoke(pick.getCreatureGenerationOptions, overrides.getCreatureGenerationOptions),
            invoke(pick.dropWorld, overrides.dropWorld),
            invoke(pick.getAbilitiesBySkill, overrides.getAbilitiesBySkill),
            invoke(pick.getJob, overrides.getJob),
            invoke(pick.listWorlds, overrides.listWorlds),
            invoke(pick.createWorld, overrides.createWorld),
            invoke(pick.createSession, overrides.createSession)
        ];
    };
    return { all, pick };
}
